using Microsoft.AspNetCore.Mvc;using System.Text.Json;
public class EventsController(RaceDayApi api):Controller{
 bool In=>HttpContext.Session.GetInt32("UserID")!=null;bool Org=>HttpContext.Session.GetString("Role")=="Organiser";
 public async Task<IActionResult> Index()=>View(await api.Get<List<JsonElement>>("api/events")??new());
 public async Task<IActionResult> Details(int id){ViewBag.Categories=await api.Get<List<JsonElement>>($"api/events/{id}/categories")??new();var e=await api.Get<JsonElement>($"api/events/{id}");return e.ValueKind==JsonValueKind.Undefined?NotFound():View(e);}
 [HttpGet]public IActionResult Create(){if(!In)return RedirectToAction("Login","Account");if(!Org)return Forbid();return View(new EventVm());}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Create(EventVm m){if(!In)return RedirectToAction("Login","Account");if(!Org)return Forbid();if(!ModelState.IsValid)return View(m);var p=new{eventName=m.EventName,eventDate=m.EventDate,startTime=m.StartTime,endTime=m.EndTime,venue=m.Venue,location=m.Location,description=m.Description,maxParticipants=m.MaxParticipants,status=m.Status};var r=await api.Send(HttpMethod.Post,"api/events",p);if(!r.ok){ModelState.AddModelError("","API error: "+r.body);return View(m);}TempData["Message"]="Event created.";return RedirectToAction(nameof(Index));}
 [HttpGet]public async Task<IActionResult> Edit(int id){if(!In)return RedirectToAction("Login","Account");if(!Org)return Forbid();var e=await api.Get<JsonElement>($"api/events/{id}");if(e.ValueKind==JsonValueKind.Undefined)return NotFound();return View(new EventVm{EventID=id,EventName=e.GetProperty("eventName").GetString()??"",EventDate=e.GetProperty("eventDate").GetDateTime(),StartTime=TimeSpan.Parse(e.GetProperty("startTime").GetString()!),EndTime=TimeSpan.Parse(e.GetProperty("endTime").GetString()!),Venue=e.GetProperty("venue").GetString()??"",Location=e.GetProperty("location").GetString()??"",Description=e.GetProperty("description").GetString(),MaxParticipants=e.GetProperty("maxParticipants").GetInt32(),Status=e.GetProperty("status").GetString()??"Open"});}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Edit(EventVm m){if(!In)return RedirectToAction("Login","Account");if(!Org)return Forbid();if(!ModelState.IsValid)return View(m);var p=new{eventName=m.EventName,eventDate=m.EventDate,startTime=m.StartTime,endTime=m.EndTime,venue=m.Venue,location=m.Location,description=m.Description,maxParticipants=m.MaxParticipants,status=m.Status};var r=await api.Send(HttpMethod.Put,$"api/events/{m.EventID}",p);if(!r.ok){ModelState.AddModelError("","Update failed: "+r.body);return View(m);}return RedirectToAction(nameof(Index));}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Delete(int id){if(!In)return RedirectToAction("Login","Account");if(!Org)return Forbid();var r=await api.Send<object>(HttpMethod.Delete,$"api/events/{id}");TempData["Message"]=r.ok?"Event deleted.":"Delete failed.";return RedirectToAction(nameof(Index));}
 [HttpGet]public IActionResult Category(int id){if(!In)return RedirectToAction("Login","Account");if(!Org)return Forbid();return View(new CategoryVm{EventID=id});}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Category(CategoryVm m){if(!In)return RedirectToAction("Login","Account");if(!Org)return Forbid();if(!ModelState.IsValid)return View(m);var r=await api.Send(HttpMethod.Post,$"api/events/{m.EventID}/categories",m);if(!r.ok){ModelState.AddModelError("","Category could not be saved.");return View(m);}return RedirectToAction(nameof(Details),new{id=m.EventID});}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Enrol(EnrolVm m){if(!In)return RedirectToAction("Login","Account");if(HttpContext.Session.GetString("Role")!="Participant")return Forbid();var r=await api.Send(HttpMethod.Post,"api/enrolments",m);TempData["Message"]=r.ok?"Enrolment recorded.":"Enrolment failed: "+r.body;return RedirectToAction(nameof(Details),new{id=m.EventID});}
}